import numpy as np, re, requests, pandas as pd
import matplotlib.pyplot as plt
exec(open("/dev/null").read()) if False else None

def read_ca(path):
    out={}
    for l in open(path):
        if not l.startswith("ATOM") or l[12:16].strip()!="CA" or l[16] not in (" ","A"): continue
        out[int(l[22:26])]=(np.array([float(l[30:38]),float(l[38:46]),float(l[46:54])]), l[17:20], float(l[60:66]))
    return out
t2o={'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H','ILE':'I',
     'LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V'}
def kabsch(P,Q):
    pc,qc=P.mean(0),Q.mean(0); H=(P-pc).T@(Q-qc); U,S,Vt=np.linalg.svd(H)
    d=np.sign(np.linalg.det(Vt.T@U.T)); R=Vt.T@np.diag([1,1,d])@U.T; return R,qc-R@pc
def lis(v):
    n=len(v); b=[1]*n; p=[-1]*n
    for i in range(n):
        for j in range(i):
            if v[j]<v[i] and b[j]+1>b[i]: b[i]=b[j]+1; p[i]=j
    i=int(np.argmax(b)); o=[]
    while i!=-1: o.append(i); i=p[i]
    return sorted(o)
def struct_align(ref,mob,seed,n_iter=12):
    pairs=list(seed); rk=sorted(ref); mk=sorted(mob); MM=np.array([mob[k][0] for k in mk])
    for it in range(n_iter):
        P=np.array([mob[b][0] for a,b in pairs]); Q=np.array([ref[a][0] for a,b in pairs])
        R,t=kabsch(P,Q); MT=(R@MM.T).T+t
        c=9.0 if it<3 else (6.0 if it<6 else 4.0); cand=[]
        for a in rk:
            d=np.linalg.norm(MT-ref[a][0],axis=1); j=int(np.argmin(d))
            if d[j]<c: cand.append((a,mk[j]))
        cand.sort(); new=[cand[i] for i in lis([b for a,b in cand])]
        if len(new)<15 or new==pairs: break
        pairs=new
    P=np.array([mob[b][0] for a,b in pairs]); Q=np.array([ref[a][0] for a,b in pairs])
    R,t=kabsch(P,Q); dd=np.sqrt((((R@P.T).T+t-Q)**2).sum(1))
    return pairs,float(np.sqrt((dd**2).mean())),dict(zip([a for a,b in pairs],dd))

ACC={"Tsr":"P02942","McpB":"P39215","McpC":"P54576","McpA":"P39214","TlpA":"P39216","TlpB":"P39217"}
S={k:"".join(requests.get(f"https://rest.uniprot.org/uniprotkb/{a}.fasta",timeout=30).text.strip().split("\n")[1:]) for k,a in ACC.items()}
tipp={k:re.search(r"G[FLIV][ASG]VVA[DEG]EVR",s).start()+1 for k,s in S.items()}
TMend={"Tsr":210,"McpB":303,"McpC":297,"McpA":302}
