            seq_check=(S[nm][q-1] if q else None), is_Gln=(S[nm][q-1]=="Q" if q else False),
            ca_dev_A=(round(dev[p],2) if q else None), plddt=(round(mob[q][2],1) if q else None),
            n_aligned=len(pairs), global_rmsd_A=round(rms,2)))
T=pd.DataFrame(rows); T.to_csv("structural_column_table.csv",index=False)
